                    os.chmod(p, want); changed += 1
            except OSError as e:
                failed += 1; print("file-error %s %s" % (p, e), flush=True)
        try:
            if stat.S_IMODE(os.lstat(dirpath).st_mode) != DIR_MODE:
                os.chmod(dirpath, DIR_MODE); changed += 1
        except OSError as e:
            failed += 1; print("dir-error %s %s" % (dirpath, e), flush=True)
    try:
        if stat.S_IMODE(os.lstat(root).st_mode) != DIR_MODE:
            os.chmod(root, DIR_MODE); changed += 1
    except OSError as e:
        failed += 1; print("root-error %s %s" % (root, e), flush=True)
print("paths_changed=%d failures=%d" % (changed, failed), flush=True)
# Verify: nothing world-accessible, nothing group-writable.
bad = []
for root in roots:
    for dirpath, _, filenames in os.walk(root):
        for p in [dirpath] + [os.path.join(dirpath, n) for n in filenames]:
            m = stat.S_IMODE(os.lstat(p).st_mode)
            if m & 0o007 or m & 0o022:
                bad.append((p, oct(m)))
